<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Localiza Workshop API</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-slate-950 text-white"><main class="max-w-6xl mx-auto p-8"><div class="rounded-3xl bg-emerald-500 p-8 text-slate-950"><p class="font-bold">COPILOT STUDIO WORKSHOP</p><h1 class="text-4xl font-black mt-2">API de Mobilidade & Frotas</h1><p class="mt-3">Sandbox educacional inspirado em cenários de locação. Não representa API oficial da Localiza.</p></div><div id="app" class="grid md:grid-cols-2 gap-4 mt-6"></div></main><script>const groups={'Reservas':['POST /api/v1/reservations','GET /api/v1/vehicles','POST /api/v1/coupons/applications'],'Telemetria':['GET /api/v1/vehicles/{id}/telemetry','PUT /api/v1/vehicles/{id}/driver','POST /api/v1/vehicles/{id}/geofences'],'Operação':['POST /api/v1/claims','POST /api/v1/maintenance-appointments','GET /api/v1/vehicles/{id}/maintenance-history'],'Financeiro':['GET /api/v1/billing-statements','GET /api/v1/traffic-fines']};app.innerHTML=Object.entries(groups).map(([g,x])=>`<section class="bg-slate-900 rounded-2xl p-5"><h2 class="text-xl font-bold text-emerald-400">${g}</h2>${x.map(e=>`<code class="block mt-3 bg-slate-800 rounded p-3">${e}</code>`).join('')}</section>`).join('')</script></body></html>